const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function wrap(term,body){
  const label=esc(`${term.term}: ${term.visual||term.definition_en}`);
  return `<figure class="technical-visual"><svg viewBox="0 0 320 180" role="img" aria-label="${label}">${body}</svg><figcaption>${esc(term.visual||'Dock and logistics schematic')}</figcaption></figure>`;
}

